-- First Italian article translations (phase 3 of the "all six languages"
-- rollout). Same 5 articles as the German/Spanish first batches -- Male
-- Airport, the Gaafu Atoll fishing guide, fishing techniques, fishing
-- seasons, and "Where Is Maldives Located" -- keeping coverage even
-- across languages. Same conventions: canonical English entity_id kept,
-- own Italian slug/title/body, internal links inside the body still point
-- at the English URLs (those verticals aren't translated yet).
-- FIX (applied after discovering the bug): entity_id below is resolved via a
-- scalar subquery on the canonical English article slug, NOT a hardcoded
-- UUID literal. nodes.id is generated by gen_random_uuid() at insert time with
-- no explicit id column in the seeding migration, so the same article gets a
-- different random UUID in every database (local sandbox vs. production). A
-- literal UUID captured from one database's nodes table will never match row
-- in another, causing translations_entity_id_fkey violations. Resolving by
-- slug instead makes this migration portable across any database that has
-- run the legacy_articles seed migration.
insert into translations (entity_id, entity_type, locale, slug, title, short_description, description, body_html, meta_title, meta_description, translation_status, translated_by) values
  ((select id from nodes where node_type = 'article' and slug = 'male-airport-velana-international-airport'), 'article', 'it', 'aeroporto-di-male-velana-international-airport', 'Aeroporto di Malé | Velana International Airport', 'Scopri tutto ciò che devi sapere sull''Aeroporto di Malé, noto anche come Velana International Airport, la principale porta d''accesso alle Maldive. Informazioni su voli, strutture e altro ancora.', null, '<h2>Introduzione</h2><p>Il Velana International Airport, ampiamente conosciuto come l''Aeroporto di <a href="/maldives/islands/male/">Malé</a>, è la principale porta d''accesso internazionale alle straordinarie isole delle Maldive. Situato sull''isola di Hulhulé, a breve distanza dalla capitale Malé, questo aeroporto è uno snodo cruciale per i viaggiatori da tutto il mondo. Con strutture all''avanguardia, un''ampia connettività e servizi di prim''ordine, l''Aeroporto di Malé svolge un ruolo vitale nell''industria turistica maldiviana, gestendo milioni di passeggeri ogni anno.</p><p>Le Maldive sono rinomate per le loro spiagge idilliache, le acque cristalline e i resort di lusso. Che tu stia arrivando per una vacanza in famiglia, una fuga romantica o un viaggio avventuroso in solitaria, il tuo soggiorno inizia al Velana International Airport. Questa guida offre uno sguardo approfondito su tutto ciò che c''è da sapere sull''Aeroporto di Malé, inclusa la sua storia, le strutture, le opzioni di trasporto e consigli di viaggio.</p><h4>Navigazione rapida</h4><p>Panoramica dell''aeroporto Informazioni sui voli Strutture e servizi Trasporti e accessibilità Consigli di viaggio per il Velana International Airport Mappa dell''aeroporto delle Maldive Cosa fare all''aeroporto delle Maldive Elenco degli aeroporti delle Maldive Domande frequenti</p><h2>Panoramica dell''aeroporto</h2><p>Il Velana International Airport (IATA: MLE, ICAO: VRMM) è l''aeroporto più trafficato e importante delle Maldive, e funge da punto di ingresso principale sia per i turisti internazionali che per i viaggiatori nazionali. La sua posizione strategica sull''isola di Hulhulé, adiacente alla capitale Malé, lo rende uno snodo essenziale per il trasporto aereo nella regione.</p><p>Originariamente noto come Hulhulé Airport, è stato inaugurato nel 1960 e da allora ha subito diverse espansioni e aggiornamenti per far fronte al crescente numero di visitatori delle Maldive. Nel 2017 l''aeroporto è stato rinominato Velana International Airport in onore di Ibrahim Nasir, il secondo presidente delle Maldive, che ha svolto un ruolo significativo nello sviluppo della nazione. Oggi il Velana International Airport dispone di strutture moderne, tra cui una nuova pista in grado di gestire i velivoli più grandi al mondo, come l''Airbus A380.</p>', 'Aeroporto di Malé | Velana International Airport | Guida di Viaggio alle Maldive | MTG', 'Scopri tutto ciò che devi sapere sull''Aeroporto di Malé, noto anche come Velana International Airport, la principale porta d''accesso alle Maldive. Informazioni su voli, strutture e altro ancora.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'gaafu-atoll-fishing-guide-mfh-maamendhoo'), 'article', 'it', 'pesca-atollo-gaafu-guida-lodge-charter-maamendhoo', 'Pesca nell''Atollo di Gaafu: Guida al nostro lodge e charter a Maamendhoo', 'La barca da charter, i prezzi e i pacchetti di più notti che offriamo dal nostro lodge a Maamendhoo, Atollo di Gaafu Alifu.', null, '<p>Maamendhoo, un''isola nell''Atollo di Gaafu Alifu, nel sud delle Maldive, ospita il nostro lodge e l''attività di charter che vi opera accanto. Questa guida illustra la barca, i prezzi del charter e i pacchetti di più notti costruiti attorno ad essa.</p><figure><img src="uploads/assets/uploads/hotels/maldives-fishing/maldives-fishing-and-holidays-lodge.jpeg" alt="Maldives Fishing and Holidays Lodge, Maamendhoo, Atollo di Gaafu Alifu" loading="lazy" /></figure><h2>Il lodge</h2><p><a href="/maldives/guesthouses/maldives-fishing-and-holidays-lodge/">Il nostro lodge</a> è una pensione a Maamendhoo con camere a pensione completa per un massimo di 2 ospiti ciascuna, gestita dallo stesso operatore dei charter di pesca — quindi alloggio e pesca si prenotano in un unico posto anziché organizzarli separatamente.</p><figure><img src="uploads/assets/uploads/hotels/maldives-fishing/maldives-fishing-and-holidays-lodge-hotel.jpeg" alt="Maldives Fishing and Holidays Lodge" loading="lazy" /></figure><h2>La barca</h2><p>I charter si svolgono a bordo di "Emperor", una barca da pesca di 32 piedi con due motori fuoribordo da 200 CV e una capacità massima di 5 passeggeri.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/fishing-charter-boat.webp" alt="Barca da charter per la pesca alle Maldive" loading="lazy" /></figure><h2>Prezzi del charter privato</h2><p>Due charter privati sono prenotabili direttamente, con prezzo per barca anziché per persona:</p><ul><li><a href="/maldives/fishing/private-full-day-fishing-charter/">Charter di pesca privato per l''intera giornata</a> — a partire da 1.380 USD a barca, circa 8 ore.</li><li><a href="/maldives/fishing/private-half-day-fishing-charter/">Charter di pesca privato di mezza giornata</a> — a partire da 980 USD a barca, circa 4 ore.</li></ul><h2>Pacchetti di pesca di più notti</h2><p>Oltre ai due charter singoli, l''operatore propone 14 pacchetti di più notti da 2 a 8 notti, ciascuno disponibile in formato di pesca per l''intera giornata o mezza giornata, che includono il soggiorno nel lodge, un volo nazionale andata e ritorno, il trasferimento in barca e il corrispondente numero di giornate di charter. I prezzi sono scaglionati in base alla dimensione del gruppo, da 1 a 5 ospiti che condividono la barca, con 5 ospiti che ottengono la migliore tariffa a persona. Il <a href="/maldives/packages/2-night-maldives-fishing-package-full-day-fishing/">pacchetto di 2 notti</a> e il <a href="/maldives/packages/8-night-maldives-fishing-package-full-day-fishing/">pacchetto di 8 notti</a> segnano i due estremi di questa gamma — consulta l''<a href="/maldives/packages/fishing/">elenco completo dei pacchetti di pesca</a> per tutte le durate disponibili.</p><h2>Come arrivare</h2><p>I pacchetti organizzati attorno a Maamendhoo combinano un volo nazionale andata e ritorno con un trasferimento in barca verso l''isola, organizzato come parte del pacchetto anziché prenotato separatamente.</p><h2>Prenotazioni</h2><p>Tutto quanto sopra sono prenotazioni su richiesta — contattaci tramite la <a href="/maldives/providers/maldives-fishing-and-holiday/">pagina dell''operatore</a>, oppure inizia direttamente dalla pagina del charter o del pacchetto più adatto al tuo viaggio.</p>', 'Pesca nell''Atollo di Gaafu: Guida al nostro lodge e charter a Maamendhoo | Guida di Viaggio alle Maldive | MTG', 'La barca da charter, i prezzi e i pacchetti di più notti che offriamo dal nostro lodge a Maamendhoo, Atollo di Gaafu Alifu.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'maldives-fishing-techniques-guide'), 'article', 'it', 'tecniche-pesca-maldive-traina-jigging-popping-lenza-mano', 'Tecniche di pesca alle Maldive: Traina, jigging, popping e pesca con lenza a mano spiegate', 'Una guida semplice alle principali tecniche di pesca utilizzate negli atolli maldiviani — traina, jigging, popping e pesca con lenza a mano — e quali specie ciascuna di esse ha come bersaglio.', null, '<p>La maggior parte delle uscite di pesca prenotate alle Maldive rientra in una manciata di tecniche, ciascuna adatta a specie e tratti d''acqua diversi. Questa guida spiega cosa comporta ciascuna e cosa è probabile catturare con essa.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/maldives-atoll-aerial-view.webp" alt="Vista aerea di un atollo delle Maldive" loading="lazy" /></figure><h2>Traina (Trolling)</h2><p>La traina consiste nel trascinare lenze con esche o bocconi dietro una barca in movimento, tipicamente lungo i bordi di un atollo o un dislivello di reef dove passano i pesci pelagici. È la tecnica standard per il wahoo — tra i pesci più veloci dell''oceano, capace di velocità fino a 80 km/h — ed è usata anche per il tonno pinna gialla e il lampuga, spesso trovati vicino a detriti galleggianti.</p><figure><img src="legacy/fishing/images/wahoo-in-maldives.webp" alt="Wahoo alle Maldive" loading="lazy" /></figure><h2>Jigging</h2><p>Il jigging muove verticalmente un''esca metallica zavorrata vicino al fondale, su pendii e dislivelli di reef profondi anziché sull''acqua aperta coperta dalla traina. È il metodo più associato al tonno dentice, un predatore solitario e combattivo che vive esattamente in questo tipo di strutture.</p><figure><img src="legacy/fishing/images/dogtooth-tuna-in-maldives.webp" alt="Tonno dentice alle Maldive" loading="lazy" /></figure><h2>Popping</h2><p>Il popping lancia un''esca da superficie verso i bordi del reef e i canali e la recupera con scatti bruschi e schizzanti per provocare un attacco dalla superficie anziché dalle profondità. È la tecnica più strettamente legata al trevally gigante, per il quale le Maldive sono considerate a livello internazionale tra le migliori destinazioni.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/giant-trevally.webp" alt="Trevally gigante catturato pescando alle Maldive" loading="lazy" /></figure><h2>Pesca con lenza a mano e pesca di fondo</h2><p>La pesca con lenza a mano — mulinello, lenza, amo ed esca, gestiti a mano anziché lanciati e recuperati — è la tecnica tradizionale con la barriera d''ingresso più bassa, offerta comunemente come escursione introduttiva al tramonto e senza richiedere esperienza precedente. È anche alla base della storica industria maldiviana della pesca del tonnetto striato con canna e lenza. La pesca di fondo, una tecnica strettamente correlata praticata all''ancora sopra strutture di reef, è il metodo abituale per catturare cernie e lutiani.</p><figure><img src="legacy/images/fishing/tuna-fish-in-maldives.webp" alt="Tonnetto striato alle Maldive" loading="lazy" /></figure><figure><img src="uploads/assets/uploads/fishing/images/gallery/reef-fishing-grouper.webp" alt="Cernia pescata sulla barriera corallina alle Maldive" loading="lazy" /></figure><h2>Scegliere una tecnica</h2><p>Se vuoi una prima uscita facile e conviviale, la pesca con lenza a mano o un''escursione al tramonto non richiedono esperienza. Se cerchi una specie trofeo specifica, la tecnica segue il pesce: traina per wahoo e tonno, jigging per il tonno dentice, popping per il trevally gigante. I nostri <a href="/maldives/providers/maldives-fishing-and-holiday/">charter privati</a> da Maamendhoo coprono traina e pesca di fondo a bordo di "Emperor" — consulta la nostra pagina del <a href="/maldives/fishing/private-full-day-fishing-charter/">charter per l''intera giornata</a>, oppure sfoglia la <a href="/maldives/fishing/#fish-species">guida completa alle specie ittiche</a> per saperne di più su cosa potresti catturare.</p>', 'Tecniche di pesca alle Maldive: Traina, jigging, popping e pesca con lenza a mano spiegate | Guida di Viaggio alle Maldive | MTG', 'Una guida semplice alle principali tecniche di pesca utilizzate negli atolli maldiviani — traina, jigging, popping e pesca con lenza a mano — e quali specie ciascuna di esse ha come bersaglio.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'maldives-fishing-seasons-month-by-month-guide'), 'article', 'it', 'stagioni-pesca-maldive-guida-mese-per-mese', 'Stagioni di pesca alle Maldive: Guida mese per mese', 'Quando puntare a ciascuna specie negli atolli delle Maldive — dalla stagione del tonno e del wahoo durante il monsone di nord-est fino alla successiva stagione del trevally gigante.', null, '<p>Le condizioni di pesca intorno alle Maldive cambiano con le due stagioni monsoniche del paese, e diverse specie per cui i pescatori viaggiano fin qui hanno una propria stagione all''interno di questo schema. Questa guida espone cosa è realisticamente più produttivo e quando, basandosi sugli stessi dati sulle specie utilizzati in tutta la nostra <a href="/maldives/fishing/">guida alla pesca delle Maldive</a>.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/fishing-liveaboard-maldives.webp" alt="Liveaboard di pesca alle Maldive" loading="lazy" /></figure><h2>I due monsoni</h2><p>Le Maldive si trovano in un clima monsonico tropicale con due grandi stagioni. Il monsone di nord-est, localmente chiamato Iruvai, dura all''incirca da dicembre ad aprile e porta mari più calmi e meno pioggia — la finestra più prevedibile per uscite in barca di qualsiasi tipo. Il monsone di sud-ovest, Hulhangu, dura all''incirca da maggio a novembre, con più pioggia e acque più agitate in una giornata qualsiasi, anche se le uscite continuano durante tutto il periodo e alcune delle migliori specie da pesca sportiva sono più attive in questo momento.</p><h2>Stagione migliore per specie</h2><p>Questi sono gli schemi stagionali dietro le specie trattate nella nostra <a href="/maldives/fishing/#fish-species">guida alle specie ittiche</a>:</p><ul><li><strong>Tonno pinna gialla</strong> — da dicembre a marzo, durante il monsone di nord-est, più calmo.</li><li><strong>Wahoo</strong> — da dicembre a marzo, nella stessa finestra, tipicamente catturato a traina.</li><li><strong>Lampuga (Mahi-Mahi)</strong> — da dicembre ad aprile, spesso vicino a detriti galleggianti e FAD (dispositivi di aggregazione dei pesci).</li><li><strong>Tonno dentice</strong> — da novembre ad aprile, sui pendii e dislivelli di reef più profondi.</li><li><strong>Trevally gigante</strong> — da aprile a ottobre, a cavallo della transizione verso il monsone di sud-ovest.</li><li><strong>Tonnetto striato</strong> — tutto l''anno, la spina dorsale della tradizionale industria maldiviana della pesca con canna e lenza.</li></ul><h2>Da dicembre ad aprile: la stagione del monsone di nord-est</h2><p>Questa è la finestra in cui tonno pinna gialla, wahoo e lampuga sono tutti in stagione contemporaneamente, e i mari più calmi rendono le giornate in acqua più confortevoli e le condizioni di traina lungo i bordi dell''atollo migliori.</p><figure><img src="legacy/fishing/images/yellowfin-tuna.webp" alt="Tonno pinna gialla alle Maldive" loading="lazy" /></figure><figure><img src="legacy/fishing/images/wahoo-in-maldives.webp" alt="Wahoo alle Maldive" loading="lazy" /></figure><h2>Da aprile a ottobre: stagione del trevally gigante</h2><p>Man mano che la stagione si sposta verso il monsone di sud-ovest, il trevally gigante entra in stagione. I GT sono considerati il bersaglio simbolo della pesca sportiva alle Maldive, pattugliano bordi di reef e canali e sono noti per attacchi esplosivi — il paese è considerato tra le migliori destinazioni al mondo per trevally giganti di taglia trofeo.</p><figure><img src="legacy/images/fishing/giant-trevally-fish.webp" alt="Trevally gigante alle Maldive" loading="lazy" /></figure><h2>Prenotare in base alla stagione</h2><p>La nostra <a href="/maldives/providers/maldives-fishing-and-holiday/">attività di charter</a> offre charter privati tutto l''anno da Maamendhoo, nell''Atollo di Gaafu Alifu, a bordo della barca "Emperor" — consulta le nostre pagine del charter per <a href="/maldives/fishing/private-full-day-fishing-charter/">l''intera giornata</a> e <a href="/maldives/fishing/private-half-day-fishing-charter/">mezza giornata</a> per i prezzi attuali, oppure leggi l''articolo completo nella nostra <a href="/maldives/travel-guide/gaafu-atoll-fishing-guide-mfh-maamendhoo/">guida alla pesca dell''Atollo di Gaafu</a>.</p>', 'Stagioni di pesca alle Maldive: Guida mese per mese | Guida di Viaggio alle Maldive | MTG', 'Quando puntare a ciascuna specie negli atolli delle Maldive — dalla stagione del tonno e del wahoo durante il monsone di nord-est fino alla successiva stagione del trevally gigante.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'where-is-maldives-located'), 'article', 'it', 'dove-si-trovano-le-maldive', 'Dove si trovano le Maldive?', 'Dove si trovano le Maldive? Scopri dove si trova questo paradiso tropicale e perché è una delle destinazioni preferite dai viaggiatori di tutto il mondo.', null, '<h2>Una panoramica sulla posizione delle Maldive</h2><p>Le Maldive, ufficialmente Repubblica delle Maldive, sono un paradiso tropicale situato nell''Oceano Indiano. Situate a sud-ovest dello Sri Lanka e dell''India, le Maldive sono una catena di 26 atolli composti da oltre 1.000 isole coralline. Questa splendida nazione è rinomata per le sue straordinarie spiagge di sabbia bianca, le acque turchesi cristalline e le vivaci barriere coralline, che la rendono una destinazione ambita per i viaggiatori in cerca di tranquillità e bellezza naturale.</p><h2>Mappa delle Maldive</h2><h2>Coordinate geografiche</h2><figure><img src="legacy/images/maps/maldives-location-map.webp" alt="Mappa di localizzazione delle Maldive" loading="lazy" /></figure><p>Le Maldive si trovano strategicamente a circa 7 gradi a nord dell''equatore, il che conferisce loro un clima caldo e tropicale tutto l''anno. Le coordinate geografiche delle Maldive sono approssimativamente 3°15'' di latitudine nord e 73°00'' di longitudine est. Questa posizione colloca le Maldive in mezzo all''Oceano Indiano, lontano da qualsiasi grande massa continentale, contribuendo alla loro atmosfera appartata e tranquilla.</p><h2>Vicinanza ai paesi limitrofi</h2><figure><img src="legacy/images/maps/location-of-maldives.webp" alt="Posizione delle Maldive" loading="lazy" /></figure><p>Le Maldive si trovano a circa 700 chilometri a sud-ovest dello Sri Lanka e 400 chilometri a sud-ovest dell''India. Questa vicinanza al Sud Asia rende le Maldive facilmente raggiungibili in aereo dalle principali città della regione, come Colombo, Mumbai e Bangalore. La capitale <a href="/maldives/islands/male/">Malé</a>, situata su una delle isole, funge da principale porta d''accesso alle Maldive, con un aeroporto internazionale che collega il paese al resto del mondo.</p><h2>Gli atolli delle Maldive</h2><figure><img src="legacy/images/maps/maldives-atoll-map.webp" alt="Mappa degli atolli delle Maldive" loading="lazy" /></figure><p>Le Maldive sono composte da 26 atolli naturali, distribuiti su circa 90.000 chilometri quadrati. Questi atolli sono suddivisi in 20 regioni amministrative, ciascuna composta da numerose piccole isole. La particolarità delle Maldive è che la loro superficie terrestre è relativamente piccola, pur estendendosi su una vasta area oceanica. L''atollo più grande delle Maldive è l''Atollo di Baa, che è anche una Riserva della Biosfera UNESCO, noto per la sua ricca biodiversità e il suo ambiente marino incontaminato.</p><h2>Importanza della posizione delle Maldive</h2><figure><img src="legacy/images/maps/indian-ocean.webp" alt="Importanza della posizione delle Maldive" loading="lazy" /></figure><p>La posizione delle Maldive è significativa per diversi motivi. In primo luogo, la vicinanza all''equatore garantisce un clima caldo e soleggiato tutto l''anno, rendendola una destinazione perfetta per gli amanti del mare e degli sport acquatici. In secondo luogo, l''isolamento delle Maldive in mezzo all''Oceano Indiano offre un senso di lontananza ed esclusività molto apprezzato dai turisti in cerca di una fuga tranquilla. Infine, le acque oceaniche circostanti ospitano alcune delle più belle barriere coralline e forme di vita marina al mondo, rendendo le Maldive una destinazione ideale per lo snorkeling e le immersioni.</p><h2>Come arrivare alle Maldive</h2><p>Arrivare alle Maldive è relativamente semplice, con voli diretti disponibili da diverse grandi città del mondo. La maggior parte dei visitatori arriva al Velana International Airport, situato sull''isola di Hulhulé, vicino alla capitale Malé. Da lì, i viaggiatori raggiungono le isole resort in motoscafo, idrovolante o volo nazionale, a seconda della distanza dall''aeroporto. La posizione remota delle Maldive significa che, una volta arrivati, si è circondati dalla tranquillità dell''oceano, con nient''altro che il suono delle onde ad accompagnare il soggiorno.</p><h2>Conclusione: un remoto paradiso tropicale</h2><p>La posizione delle Maldive in mezzo all''Oceano Indiano le rende una destinazione davvero unica. Il loro contesto geografico, unito alla bellezza naturale e all''ambiente tranquillo, attrae visitatori da tutto il mondo. Che tu stia pianificando una fuga romantica, una vacanza in famiglia o una vacanza ricca di avventura, le Maldive offrono qualcosa per tutti, sullo sfondo di uno dei luoghi più belli della Terra.</p>', 'Dove si trovano le Maldive? | Guida di Viaggio alle Maldive | MTG', 'Dove si trovano le Maldive? Scopri dove si trova questo paradiso tropicale e perché è una delle destinazioni preferite dai viaggiatori di tutto il mondo.', 'published', 'claude')
on conflict (entity_id, locale) do update set
  slug = excluded.slug, title = excluded.title, short_description = excluded.short_description,
  body_html = excluded.body_html, meta_title = excluded.meta_title, meta_description = excluded.meta_description,
  translation_status = excluded.translation_status, translated_by = excluded.translated_by, updated_at = now();
